#include "pulsetrace/database.hpp"
#include "pulsetrace/monthly_traffic.hpp"
#include "pulsetrace/raw_input_host.hpp"
#include <sqlite3.h>
#include <fstream>
#include <iostream>
using namespace pulsetrace;
int wmain(int argc,wchar_t **argv){try{if(argc!=3)throw std::runtime_error("--create DIR | --verify DIR");const std::filesystem::path directory=argv[2];if(std::wstring(argv[1])==L"--create"){
 std::filesystem::create_directories(directory);if(std::filesystem::exists(directory/L"monitor.db"))throw std::runtime_error("Fixture destination must be new");const auto minute=utc_now_ms()/60000;Json rows=Json::array({{{"minute",minute},{"module","keyboard"},{"metric","30"},{"value",42}},{{"minute",minute},{"module","network"},{"metric","interface_upload_bytes"},{"value",1000}},{{"minute",minute},{"module","network"},{"metric","interface_download_bytes"},{"value",2000}}});{DatabaseManager db(directory/L"monitor.db");db.save("controlled-upgrade-fixture",rows);}MonthlyTrafficStore months(directory/L"network-months");months.save("controlled-upgrade-fixture",rows);
 sqlite3 *db{};auto file=(directory/L"monitor.db").u8string();if(sqlite3_open(reinterpret_cast<const char*>(file.c_str()),&db)!=SQLITE_OK)throw std::runtime_error("Fixture open failed");const auto rc=sqlite3_exec(db,"DROP TABLE network_events;DROP TABLE protocol_samples;DROP TABLE traffic_rankings;DROP TABLE app_usage;PRAGMA user_version=1;",nullptr,nullptr,nullptr);sqlite3_close(db);if(rc!=SQLITE_OK)throw std::runtime_error("Fixture downgrade failed");std::ofstream config(directory/L"config.json");config<<R"({"theme":"dark","retention_days":90,"capture_on_launch":false,"taskbar_mode":"tray","unknown_extension":{"keep":17}})";
 }else if(std::wstring(argv[1])==L"--verify"){
  DatabaseManager db(directory/L"monitor.db");const auto data=db.query(utc_now_ms()/60000-120,utc_now_ms()/60000+1,1);std::int64_t keys=0,up=0,down=0;for(const auto &row:data){if(row["module"]=="keyboard"&&row["metric"]=="30")keys+=row["value"].get<std::int64_t>();if(row["metric"]=="interface_upload_bytes")up+=row["value"].get<std::int64_t>();if(row["metric"]=="interface_download_bytes")down+=row["value"].get<std::int64_t>();}if(keys!=42||up!=1000||down!=2000)throw std::runtime_error("Historical values changed");MonthlyTrafficStore months(directory/L"network-months");const auto totals=months.query("all")["totals"];if(totals["upload_bytes"]!=1000||totals["download_bytes"]!=2000)throw std::runtime_error("Monthly archive values changed");
 }else throw std::runtime_error("Unknown fixture command");std::cout<<"Upgrade fixture verified\n";return 0;}catch(const std::exception &e){std::cerr<<e.what()<<'\n';return 1;}}
